string alphabetPyramid(int n) {
    string out;
    for (int r = 1; r <= n; ++r) {
        for (int c = 1; c <= r; ++c)          // rising: A B C ...
            out += char('A' + c - 1);
        for (int c = r - 1; c >= 1; --c)      // falling: mirror, skip the peak
            out += char('A' + c - 1);
        out += '\n';
    }
    return out;
}

int hammingWeight(uint32_t n) {
    int count = 0;
    while (n) {
        n &= (n - 1);   // clears exactly the lowest set bit
        ++count;
    }
    return count;
}

