int countPrimes(int n) {
    if (n < 3) return 0;                 // no primes strictly below 2
    vector<bool> prime(n, true);
    prime[0] = prime[1] = false;
    for (long long i = 2; i * i < n; ++i)
        if (prime[(size_t)i])
            for (long long j = i * i; j < n; j += i)   // start at i*i, not 2*i
                prime[(size_t)j] = false;
    int count = 0;
    for (int i = 2; i < n; ++i) if (prime[i]) ++count;
    return count;
}

