def count_primes(n: int) -> int:
    if n < 3:                        # no primes strictly below 2
        return 0
    prime = [True] * n
    prime[0] = prime[1] = False
    i = 2
    while i * i < n:
        if prime[i]:
            for j in range(i * i, n, i):   # start at i*i, not 2*i
                prime[j] = False
        i += 1
    return sum(prime)

