def gcd_and_lcm(a: int, b: int) -> tuple[int, int]:
    g = gcd_of(a, b)
    if g == 0:                       # both inputs zero
        return (0, 0)
    l = abs(a) // g * abs(b)         # divide FIRST, then multiply
    return (g, l)

