vector<int> addDigitArrays(const vector<int>& a, const vector<int>& b) {
    vector<int> out;
    int i = (int)a.size() - 1, j = (int)b.size() - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        int sum = carry;
        if (i >= 0) sum += a[i--];
        if (j >= 0) sum += b[j--];
        out.push_back(sum % 10);   // digit
        carry = sum / 10;          // carry
    }
    reverse(out.begin(), out.end());   // built least-significant first
    return out;
}

