def add_digit_arrays(a: list[int], b: list[int]) -> list[int]:
    out = []
    i, j, carry = len(a) - 1, len(b) - 1, 0
    while i >= 0 or j >= 0 or carry:
        total = carry
        if i >= 0:
            total += a[i]; i -= 1
        if j >= 0:
            total += b[j]; j -= 1
        out.append(total % 10)     # digit
        carry = total // 10        # carry
    return out[::-1]               # built least-significant first

