vector<int> bigFactorial(int n) {
    vector<int> d{1};                       // stores 1, least significant first
    for (int m = 2; m <= n; ++m) {
        int carry = 0;
        for (size_t i = 0; i < d.size(); ++i) {
            int temp = d[i] * m + carry;
            d[i] = temp % 10;
            carry = temp / 10;
        }
        while (carry) {                     // grow while the carry survives
            d.push_back(carry % 10);
            carry /= 10;
        }
    }
    return d;                               // reverse to print
}
